    function scaleLpScreen() {
      document.querySelectorAll('.lp-screen').forEach(function(screen) {
        var w = screen.offsetWidth;
        var scale = w / 1165;
        screen.querySelector('.lp-screen-inner').style.transform =
          'scale(' + scale + ')';
      });
    }
    scaleLpScreen();
    window.addEventListener('resize', scaleLpScreen);
  `,`
    (function() {
      var obs = new IntersectionObserver(function(entries) {
        entries.forEach(function(e) {
          if (e.isIntersecting) { e.target.classList.add('visible'); obs.unobserve(e.target); }
        });
      }, { threshold: 0.12 });
      document.querySelectorAll('.fade-in').forEach(function(el) { obs.observe(el); });
    })();
  `,`
    // Track main "See Your Building" button
    const binSubmit = document.getElementById("bin-submit");

    if (binSubmit) {
      binSubmit.addEventListener("click", function () {
        const binValue = document.getElementById("bin-input")?.value || "";

        console.log("bin_submit_click", binValue);

        if (typeof gtag === "function") {
          gtag("event", "bin_submit_click", {
            event_category: "bin_lookup",
            event_label: binValue || "empty",
            bin_number: binValue || "empty",
            debug_mode: true
          });
        }
      });
    }

    // Track example BIN buttons
    const exampleButtons = document.querySelectorAll(".bin-example-chip");

    exampleButtons.forEach(btn => {
      btn.addEventListener("click", function () {
        const exampleBin = this.dataset.bin || this.textContent.trim();

        console.log("bin_example_click", exampleBin);

        if (typeof gtag === "function") {
          gtag("event", "bin_example_click", {
            event_category: "bin_lookup",
            event_label: exampleBin || "empty",
            bin_number: exampleBin || "empty",
            debug_mode: true
          });
        }
      });
    });
  `,`
(function() {
  var vid = document.getElementById('hero-video');
  if (!vid) return;
  vid.playbackRate = 0.6;
  vid.loop = true;
  vid.play().catch(function() {});
})();
